```cpp
#include <iostream>
#include <queue>
#include <vector>
using namespace std;

// 定义节点结构体：存储当前键值、下标和保存次数
struct Node {
    long long key; // key = a[i] + t[i] * k
    int idx;      // 数组下标
    int t;        // 保留次数 t[i]
};

// 自定义比较函数：先比较 key，若相等则比较下标
struct cmp {
    bool operator()(const Node &a, const Node &b) const {
        if(a.key == b.key) return a.idx > b.idx;
        return a.key > b.key;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while(T--){
        int n, m, k;
        cin >> n >> m >> k;
        vector<long long> a(n);
        for (int i = 0; i < n; i++){
            cin >> a[i];
        }

        // 初始时所有数 t[i] = 0, key = a[i]
        priority_queue<Node, vector<Node>, cmp> pq;
        vector<int> t(n, 0);
        for(int i = 0; i < n; i++){
            pq.push({a[i], i, 0});
        }

        // 进行 m 次操作，每次从 pq 取出最小 key 的元素，将其 t 值加一后更新 key 后再入队
        for(int op = 0; op < m; op++){
            Node cur = pq.top();
            pq.pop();
            cur.t++; // 该元素保留次数加一
            t[cur.idx] = cur.t;
            cur.key = a[cur.idx] + (long long)cur.t * k; // 更新 key
            pq.push(cur);
        }

